@Component("dashboard-handler")
@ProcessingGroup("dashboard-processing-group")
public class DashboardEventHandler {
	
	// core constructor
	DashboardEventHandler(EntityManager entityManager) {
        this.entityManager = entityManager;
    }	
	
    /*
     * @param	event CreateDashboardEvent
     */
    @EventHandler
    public void handle( CreateDashboardEvent event) {
        entityManager.persist(new Dashboard(event.getDashboardId(), event.getTitle(), event.getTheme(), event.getWorkspace(), event.getVisualizations(), event.getReports(), event.getDatasets(), event.getAlerts(), event.getQueries(), event.getTags(), event.getStatus()));
    }

    /*
     * @param	event UpdateDashboardEvent
     */
    @EventHandler
    public Dashboard handle( UpdateDashboardEvent event) {
    	entityManager.merge(new Dashboard(event.getDashboardId(), event.getTitle(), event.getTheme(), event.getWorkspace(), event.getVisualizations(), event.getReports(), event.getDatasets(), event.getAlerts(), event.getQueries(), event.getTags(), event.getStatus()));
    }
    
    /*
     * @param	event DeleteDashboardEvent
     */
    @EventHandler
    public void on( DeleteDashboardEvent event) {
    	Dashboard entity = new Dashboard();
   
    	// ------------------------------------------
    	// apply the DashboardId
    	// ------------------------------------------
    	entity.setDashboardId( event.getDashboardId() );
    	
    	// ------------------------------------------
    	// add to an Iterable and delete
    	// ------------------------------------------
    	entityManager.remove( entity );
    }    
    
    // attributes
	private final DashboardRepository dashboardEntityRepository;
    private static final Logger LOGGER 			= Logger.getLogger(DashboardEventHandler.class.getName());

}
